pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PredictTheBlockHashChallenge c;

    function setUp() public {
        vm.deal(address(this), 1000000000000000000);
        c = new PredictTheBlockHashChallenge{value: 1000000000000000000}();
    }

    function _run(address sender) internal {
        vm.assume(true);
        bool reverted;
        try c.settle() { reverted = false; } catch { reverted = true; }
        assertTrue(reverted == true);
    }

    function testFuzz_run(address sender) public {
        _run(sender);
    }

    receive() external payable {}
}
